//! `navfn` and `planner` against the real nav2_navfn_planner (tests/data/navfn.json,
//! regenerated by tests/oracle/run_oracle.sh navfn).
//!
//! NavFn is `float` arithmetic with the shipped FMA contractions reproduced, so
//! its outputs (potentials, sub-cell paths) are compared bit for bit: the
//! potential arrays by a hash of their bits, the `f32` values exactly after
//! reading the JSON double back to `f32`. World poses are `f64` and compared
//! to `TOL`.

mod common;

use common::{assert_close, f, load};
use mower_nav_core::costmap::{static_costmap, Costmap2D, OccupancyGrid, StaticLayerParams};
use mower_nav_core::geometry::Pose2D;
use mower_nav_core::navfn::{hypotf, NavFn, POT_HIGH, PRIORITYBUFSIZE};
use mower_nav_core::planner::{NavfnParams, NavfnPlanner};
use serde_json::Value;

/// FNV-1a over the float bits, as the oracle's `pot_hash`.
fn pot_hash(p: &[f32]) -> u64 {
    let mut h: u64 = 14695981039346656037;
    for v in p {
        h ^= v.to_bits() as u64;
        h = h.wrapping_mul(1099511628211);
    }
    h
}

#[track_caller]
fn assert_potential(potarr: &[f32], theirs: &Value, what: &str) {
    let finite = potarr.iter().filter(|&&p| p < POT_HIGH).count() as u64;
    assert_eq!(finite, theirs["finite"].as_u64().unwrap(), "{what}: reached cells");
    assert_eq!(pot_hash(potarr), theirs["hash"].as_u64().unwrap(), "{what}: potential bits");
}

fn f32s(v: &Value) -> Vec<f32> {
    v.as_array().unwrap().iter().map(|x| f(x) as f32).collect()
}

fn bytes(v: &Value) -> Vec<u8> {
    v.as_array().unwrap().iter().map(|x| x.as_u64().unwrap() as u8).collect()
}

fn i32s(v: &Value) -> [i32; 2] {
    [v[0].as_i64().unwrap() as i32, v[1].as_i64().unwrap() as i32]
}

fn grid(v: &Value) -> OccupancyGrid {
    OccupancyGrid {
        width: v["width"].as_u64().unwrap() as u32,
        height: v["height"].as_u64().unwrap() as u32,
        resolution: f(&v["resolution"]),
        origin_x: f(&v["origin_x"]),
        origin_y: f(&v["origin_y"]),
        data: v["data"].as_array().unwrap().iter().map(|x| x.as_i64().unwrap() as i8).collect(),
    }
}

fn pose(v: &Value) -> Pose2D {
    Pose2D::new(f(&v[0]), f(&v[1]), f(&v[2]))
}

#[test]
fn hypotf_is_glibcs() {
    let d = load("navfn.json");
    let h = &d["hypot"];
    // checked exhaustively in the oracle: glibc against the formulas used here
    assert_eq!(h["hypotf_mismatches"].as_u64(), Some(0));
    assert_eq!(h["hypot_int_mismatches"].as_u64(), Some(0));
    for s in h["hypotf_samples"].as_array().unwrap() {
        let (x, y) = (f(&s[0]) as f32, f(&s[1]) as f32);
        assert_eq!(hypotf(x, y), f(&s[2]) as f32, "hypotf({x}, {y})");
    }
}

#[test]
fn set_costmap_matches_navfn() {
    let d = load("navfn.json");
    let t = &d["set_costmap"];
    let all: Vec<u8> = (0..=255).collect();
    let mut nav = NavFn::new(16, 16);
    nav.set_costmap(&all, true, true);
    assert_eq!(nav.costarr(), &bytes(&t["ros_allow_unknown"])[..]);
    nav.set_costmap(&all, true, false);
    assert_eq!(nav.costarr(), &bytes(&t["ros_no_unknown"])[..]);
    let pgm = &t["pgm"];
    let mut nav = NavFn::new(pgm["nx"].as_i64().unwrap() as i32, pgm["ny"].as_i64().unwrap() as i32);
    nav.set_costmap(&bytes(&pgm["cmap"]), false, false);
    assert_eq!(nav.costarr(), &bytes(&pgm["costarr"])[..]);
}

#[test]
fn navfn_matches_nav2() {
    let d = load("navfn.json");
    for c in d["navfn"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let (nx, ny) = (c["nx"].as_i64().unwrap() as i32, c["ny"].as_i64().unwrap() as i32);
        let cmap = if c["cmap"] == "open" { vec![0u8; (nx * ny) as usize] } else { bytes(&c["cmap"]) };

        let mut nav = NavFn::new(nx, ny);
        nav.set_costmap(&cmap, true, c["allow_unknown"].as_bool().unwrap());
        nav.set_goal(i32s(&c["goal"]));
        nav.set_start(i32s(&c["start"]));
        let mut calls = 0;
        let mut cancel = || {
            calls += 1;
            false
        };
        let result = if c["astar"].as_bool().unwrap() {
            nav.calc_nav_fn_astar(&mut cancel)
        } else {
            nav.calc_nav_fn_dijkstra(&mut cancel, c["at_start"].as_bool().unwrap())
        };
        assert_eq!(result, Ok(c["result"].as_bool().unwrap()), "{name}: result");
        assert_eq!(calls, c["cancel_calls"].as_i64().unwrap(), "{name}: cancel checks");
        assert_eq!(nav.nobs() as i64, c["nobs"].as_i64().unwrap(), "{name}: nobs");
        assert_potential(nav.potarr(), &c["potential"], name);
        if let Some(p) = c.get("potarr") {
            let theirs = f32s(p);
            let diff = nav.potarr().iter().zip(&theirs).filter(|(a, b)| a != b).count();
            assert_eq!(diff, 0, "{name}: {diff} potentials differ");
        }
        if let Some(cost) = c.get("last_path_cost") {
            assert_eq!(nav.last_path_cost(), f(cost) as f32, "{name}: last path cost");
        }
        if name == "big_open" {
            assert_eq!(nav.stats().max_buffer as usize, PRIORITYBUFSIZE, "{name}: the buffer limit is hit");
        }

        for (k, p) in c["paths"].as_array().unwrap().iter().enumerate() {
            let st = if p["st"].is_null() { None } else { Some(i32s(&p["st"])) };
            let len = nav.calc_path(p["n"].as_i64().unwrap() as i32, st);
            assert_eq!(len as i64, p["len"].as_i64().unwrap(), "{name} path {k}: length");
            assert_eq!(nav.path_x(), &f32s(&p["x"])[..], "{name} path {k}: x");
            assert_eq!(nav.path_y(), &f32s(&p["y"])[..], "{name} path {k}: y");
        }
    }
}

fn params(v: &Value) -> NavfnParams {
    NavfnParams {
        tolerance: f(&v["tolerance"]),
        use_astar: v["use_astar"].as_bool().unwrap(),
        allow_unknown: v["allow_unknown"].as_bool().unwrap(),
        use_final_approach_orientation: v["use_final_approach_orientation"].as_bool().unwrap(),
    }
}

fn changed_cells(ours: &Costmap2D, initial: &Costmap2D) -> Vec<(u64, u64)> {
    ours.data()
        .iter()
        .zip(initial.data())
        .enumerate()
        .filter(|(_, (a, b))| a != b)
        .map(|(i, (a, _))| (i as u64, *a as u64))
        .collect()
}

/// Every request of a scenario runs in order on one planner and one costmap,
/// as on the robot between two map updates: cells freed by `clearRobotCell`
/// stay free for the later requests.
#[test]
fn navfn_planner_matches_nav2() {
    let d = load("navfn.json");
    for s in d["scenarios"].as_array().unwrap() {
        let id = s["id"].as_str().unwrap();
        let g = grid(&d["grids"][s["grid"].as_str().unwrap()]);
        let initial = static_costmap(&g, &StaticLayerParams::new(true));
        let mut costmap = initial.clone();
        let mut planner = NavfnPlanner::new(params(&s["params"]), &costmap);

        for r in s["requests"].as_array().unwrap() {
            let what = format!("{id}/{}", r["name"].as_str().unwrap());
            let (start, goal) = (pose(&r["start"]), pose(&r["goal"]));
            let cancel_at = r["cancel_at"].as_i64().unwrap();
            let mut calls = 0;
            let mut cancel = || {
                calls += 1;
                cancel_at > 0 && calls >= cancel_at
            };
            let result = planner.create_plan(&mut costmap, &start, &goal, &mut cancel);

            let error = result.as_ref().err().map(|e| format!("{e:?}"));
            assert_eq!(error.as_deref(), r["error"].as_str(), "{what}: error");
            assert_eq!(calls, r["cancel_calls"].as_i64().unwrap(), "{what}: cancel checks");
            let path = result.unwrap_or_default();
            let expected = r["path"].as_array().unwrap();
            assert_eq!(path.len(), expected.len(), "{what}: poses");
            for (i, (p, e)) in path.iter().zip(expected).enumerate() {
                assert_close(p.x, f(&e[0]), &format!("{what} pose {i} x"));
                assert_close(p.y, f(&e[1]), &format!("{what} pose {i} y"));
                assert_close(p.yaw, f(&e[2]), &format!("{what} pose {i} yaw"));
            }
            if let Some(pot) = r.get("potential") {
                assert_potential(planner.navfn().potarr(), pot, &what);
            }
            let theirs: Vec<(u64, u64)> = r["changed_cells"]
                .as_array()
                .unwrap()
                .iter()
                .map(|c| (c[0].as_u64().unwrap(), c[1].as_u64().unwrap()))
                .collect();
            assert_eq!(changed_cells(&costmap, &initial), theirs, "{what}: cells cleared in the costmap");
        }
    }
}
